"""Retain paper-edition source correspondence without inferring an unstated upstream commit."""
import json,hashlib
from pathlib import Path
from prepare_signac_link_sources import extract
ROOT=Path(__file__).resolve().parents[2];BASE=ROOT/'build/literature-review/signac-runtime';DEST=ROOT/'src/main/resources/org/jlinalg/omics/chromvar-paper-sources'
def pin(raw):return dict(bytes=len(raw),sha256=hashlib.sha256(raw).hexdigest())
def main():
    assert not DEST.exists();DEST.mkdir();intake=BASE/'chromvar-historical-source-intake-1';pre=json.loads((intake/'PREPUBLICATION.json').read_bytes());records=[]
    for edition,source,uri,commit in [('1.28.0',intake/'source-1.28.0','https://bioconductor.org/packages/3.20/bioc/src/contrib/chromVAR_1.28.0.tar.gz',None),('1.5.0',intake/'source-1.5.0-prepublication','https://github.com/GreenleafLab/chromVAR/tree/'+pre['candidate_commit'],pre['candidate_commit'])]:
        folder=DEST/edition;folder.mkdir();description=(source/'DESCRIPTION').read_bytes();assert ('Version: '+edition) in description.decode();functions=[]
        for name in ['compute_expectations_core','compute_deviations_single','compute_deviations_core','get_background_peaks_core']:
            bg=name.startswith('get_');original=source/('R/background_peaks.R' if bg else 'R/compute_deviations.R');raw=extract(original.read_bytes().decode('utf8'),name);baseline=ROOT/'src/main/resources/org/jlinalg/omics'/('chromvar-background' if bg else 'chromvar-deviations')/'1.34.1'/(name+'.R');assert raw==baseline.read_bytes();resource=edition+'/'+name+'.R';(DEST/resource).write_bytes(raw);functions.append(dict(name=name,resource=resource,function=pin(raw),original_source=original.relative_to(ROOT).as_posix(),original_source_pin=pin(original.read_bytes()),validated_function_byte_identical=True))
        cpp=(source/'src/utils.cpp').read_bytes();baseline=(ROOT/'src/main/resources/org/jlinalg/omics/chromvar-background/1.34.1/utils.cpp').read_bytes();difference='byte-identical' if cpp==baseline else 'one-terminal-LF-only';assert cpp==baseline or cpp+b'\n'==baseline;(folder/'utils.cpp').write_bytes(cpp)
        lines=(source/'R/background_peaks.R').read_bytes().decode('utf8').splitlines(keepends=True);starts=[i for i,l in enumerate(lines) if 'nucfreqs <- letterFrequency' in l];assert len(starts)==2;formula=''.join(lines[starts[0]:starts[0]+2]);expected=['nucfreqs <- letterFrequency(seqs, c("A", "C", "G", "T"))','gc <- rowSums(nucfreqs[, 2:3]) / rowSums(nucfreqs)'];assert [l.strip() for l in formula.splitlines()]==expected and ''.join(lines[starts[1]:starts[1]+2])==formula;(folder/'gc_formula.R').write_bytes(formula.encode('utf8'))
        records.append(dict(profile=edition+'-source',edition=edition,functions=functions,official_source=uri,upstream_commit=commit,paper_commit_unknown=bool(commit),reference_commit_precedes_paper_publication=bool(commit),DESCRIPTION=pin(description),cpp_resource=edition+'/utils.cpp',cpp_source=pin(cpp),cpp_difference_from_current= difference,current_cpp_source=pin(baseline),gc_formula_resource=edition+'/gc_formula.R',gc_formula_matches_original_validated_expression=True,current_dependencies_explicit=True,historical_whole_package=False))
    report=dict(schema_version=1,status='exact-scoped-paper-source-correspondence',records=records,native_prepared_profile_keys=['1.16.0-source','1.34.1-package'],upstream_runtime_R='4.6.1',upstream_runtime_chromVAR='1.34.1',paper_1_5_0_exact_commit_unknown=True,reference_commit_selection='Latest official upstream commit available by P225 first publication 2024-07-29; a reference candidate, not proof of the paper commit.',R_functions_are_byte_identical=True,cpp_exception='The pre-publication upstream 1.5.0 utils.cpp lacks exactly one final LF present in the current file; all preceding bytes are identical. Raw files are retained, not repaired.',GC_expression_identical=True,whole_historical_packages_executed=False,ArchR_pipeline_available=False,required_action='Use the two explicitly supported request profile keys. These source comparisons do not reconstruct historical dependencies or prove an unstated paper commit. Preserve actual paper editions, wrapper/database/postprocessing and unknown settings; consult CHROMVAR_TOOLS.md.')
    (DEST/'SOURCE-PROFILES.json').write_text(json.dumps(report,indent=2)+'\n',encoding='utf8',newline='\n');(DEST/'MIT-LICENSE.txt').write_bytes((ROOT/'src/main/resources/org/jlinalg/omics/chromvar-deviations/MIT-LICENSE.txt').read_bytes());(DEST/'.gitattributes').write_text('*.R -text\n*.cpp -text\n*.json -text\n*.txt -text\n',encoding='utf8',newline='\n');print(json.dumps(dict(status=report['status'],profiles=2,R_functions_each=4,prepublication_commit=pre['candidate_commit'],paper_commit_unknown=True)))
if __name__=='__main__':
    if not __debug__:raise RuntimeError('Never disable exact source correspondence checks')
    main()
